CREATE OR REPLACE FUNCTION public.publish_monitor_connect_start(a uuid, p_account_project_id uuid, p_permissions text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
